    '1aa36213cb676fd5baad5edc2bee4fbe117a778b' => ['name' => 'Istraživači (Savez)', 'description' => '+10% brzine tokom putovanja do destinacije na ekspedicijama<br />+5% veći planeti tokom kolonizacije<br />Pristup falangi sustava: za 40,000 deuterija možete ju iskoristiti kako bi skenirali kompletne sustave, toliko dugo dok su unutar dometa.', 'duration_label' => 'za 40,000 deuterija možete ju iskoristiti kako bi skenirali kompletne sustave, toliko dugo dok su unutar dometa.', 'extended_description' => 'Najveća se otkrića ostvaraju kada mnogo velikih umova radi u skladu. Savez istraživača ne otkriva samo velike planete za kolonizaciju, već ujedno ima i brodove koji su brži na ekspedicijama. Zajedno imaju pristup falangi sustava, koja se može koristiti kako bi se skenirala i otkrila kretanja flota u cijelim sustavima.'],
    '6c9fe5e35bdad0d4e3382eb6a5aeac6bc8263752' => ['name' => 'Trgovci (Savez)', 'description' => '+10% brzina transportera<br />+5% proizvodnja reurrsa i energije<br />+10% kapacitet spremnika na mjesecima i planetima.', 'duration_label' => 'Trajan', 'extended_description' => 'Savezi trgovine su vrijedni za sve uključene strane, a baš nitko to ne zna bolje od saveza trgovaca. Njihovi transporteri lete brže, a procesi proizvodnje energije i resursa su optimizirani kako bi što više zaradili. Sa svojom poboljšanom logistikom također imaju više kapaciteta za pohranjivanje resursa na svojim planetima i mjesecima.'],
    '9b48e257cbef6c5df0f03a47cead7f9abda3d437' => ['name' => 'Ratnici (Savez)', 'description' => '+10% brzina brodova koji putuju između članova saveza<br />+1 za istraživanja borbe<br />+1 za istraživanja špijunaže<br />Pristup špijunaži sustava: šalje odabrani broj sondi za špijunažu kako bi skenirali cijeli sustav. Možete odabrati tip nebeskog tijela koji želite istražiti, vrijeme koje treba proći od zadnje špijunaže ili željenu aktivnost igrača.', 'duration_label' => 'šalje odabrani broj sondi za špijunažu kako bi skenirali cijeli sustav. Možete odabrati tip nebeskog tijela koji želite istražiti, vrijeme koje treba proći od zadnje špijunaže ili željenu aktivnost igrača.', 'extended_description' => 'Nekad čak i najsnažniji ratnici moraju osnovati pakt kako bi zajedno mogli vladati galaksijom. Tehnologija za špijunažu dostupna takvoj uniji omogućava im lakšu identifikaciju vrijednih meta u njihovim pohodima. Kada su zajedno, njihova je tehnologija još snažnija i spremni za apsolutno bilo što.'],
    'dc34fa00ba914ffab0031ac3f165e26f553d7809' => ['name' => 'Avatar: Laserska Mačka', 'description' => 'Odaberite ovaj avatar na svom profilu kako biste ga primijenili i profilu dali osobni dodir. Ovaj predmet biti će otključan za sve univerzume na Vašem računu. Imajte na umu da sinkronizacija između univerzuma može potrajati neko vrijeme.', 'duration_label' => 'Trajan', 'extended_description' => 'Mačke i laseri su nerazdvojna kombinacija – sada svoj profil možete okititi najboljim od oba svijeta!'],
    '1c497ef926d674f2df9d96cfc58fe12f97cf4025' => ['name' => 'Avatar: Mali Izvanzemaljac', 'description' => 'Odaberite ovaj avatar na svom profilu kako biste ga primijenili i profilu dali osobni dodir. Ovaj predmet biti će otključan za sve univerzume na Vašem računu. Imajte na umu da sinkronizacija između univerzuma može potrajati neko vrijeme.', 'duration_label' => 'Trajan', 'extended_description' => 'Novi oblici inteligentnog života neprestano se otkrivaju u golemim prostranstvima svemira. Mnogi od njih potpuno su drugačiji od ljudi, sa različitim snagama i slabostima.'],
    'fd3b0789b5dca99e9d5b251f8bae0760ce52dea6' => ['name' => 'Avatar: Nadograđen', 'description' => 'Odaberite ovaj avatar na svom profilu kako biste ga primijenili i profilu dali osobni dodir. Ovaj predmet biti će otključan za sve univerzume na Vašem računu. Imajte na umu da sinkronizacija između univerzuma može potrajati neko vrijeme.', 'duration_label' => 'Trajan', 'extended_description' => 'Znanost je odavno prevladala granice krhkog ljudskog tijela. Implantati i druga visokotehnološka poboljšanja omogućuju vam da postanete brži, čvršći i jači od drugih.'],
    '003db2a3d693c2d889864b76ad122b274bfd641b' => ['name' => 'Avatar: Bestežinsko Stanje', 'description' => 'Odaberite ovaj avatar na svom profilu kako biste ga primijenili i profilu dali osobni dodir. Ovaj predmet biti će otključan za sve univerzume na Vašem računu. Imajte na umu da sinkronizacija između univerzuma može potrajati neko vrijeme.', 'duration_label' => 'Trajan', 'extended_description' => 'Prva svemirska šetnja velika je prekretnica u karijeri svakog mladog astronauta, bez obzira na vrstu. Taj osjećaj da sami lebdite među zvijezdama, gledajući dolje na svoj maleni rodni planet, ostat će s vama do kraja vaših dana..'],
    '8d514b69eb04a57495bab0c8f4b80f58294a7b17' => ['name' => 'Avatar: Ledeno Hladan', 'description' => 'Odaberite ovaj avatar na svom profilu kako biste ga primijenili i profilu dali osobni dodir. Ovaj predmet biti će otključan za sve univerzume na Vašem računu. Imajte na umu da sinkronizacija između univerzuma može potrajati neko vrijeme.', 'duration_label' => 'Trajan', 'extended_description' => 'Ledeni planeti cijenjeni su zbog svojih bogatih naslaga deuterija, ali ponekad je potrebno povećati sigurnosne detalje. Tko zna što se krije ispod svog tog leda i snijega...'],
    '83c4e79697a264462e3ca2e8567307e7f1d7954b' => ['name' => 'Avatar: Kibernetski Prostor', 'description' => 'Odaberite ovaj avatar na svom profilu kako biste ga primijenili i profilu dali osobni dodir. Ovaj predmet biti će otključan za sve univerzume na Vašem računu. Imajte na umu da sinkronizacija između univerzuma može potrajati neko vrijeme.', 'duration_label' => 'Trajan', 'extended_description' => 'Mnogi mladi revolveraši koji se nadaju da će svoje bogatstvo zaraditi među zvijezdama razvijaju vlastiti stil tijekom svoje karijere. To im pomaže da steknu ugled i povećaju svoj položaj u sumnjivijim krugovima.'],
    '2d7de180f3f3d191982294d2f8c1cd7507e90cb4' => ['name' => 'Avatar: Retro Mačići', 'description' => 'Odaberite ovaj avatar na svom profilu kako biste ga primijenili i profilu dali osobni dodir. Ovaj predmet biti će otključan za sve univerzume na Vašem računu. Imajte na umu da sinkronizacija između univerzuma može potrajati neko vrijeme.', 'duration_label' => 'Trajan', 'extended_description' => 'Legende govore o slatkom i ljupkom mačiću koji za sobom vuče duge dok leti beskrajnim prostranstvima svemira. Neki razotkrivači pokušali su objasniti te mitove kao ništa više od problema sa sustavom za filtriranje plinova u kokpitu, ali tko zna...'],
    'c54d5a8f36f20373c5bb633a109241290b2e2a7a' => ['name' => 'Avatar: Donosilac Rata', 'description' => 'Odaberite ovaj avatar na svom profilu kako biste ga primijenili i profilu dali osobni dodir. Ovaj predmet biti će otključan za sve univerzume na Vašem računu. Imajte na umu da sinkronizacija između univerzuma može potrajati neko vrijeme.', 'duration_label' => 'Trajan', 'extended_description' => 'Oni koji vladaju željeznom rukom često su vrlo oprezni oko stvaranja opasne persone. Ljudi koji im dolaze uputiti molbu ili odati počast trebali bi odmah prepoznati s kim imaju posla.'],
    '99f53568108115acac2d7f7425ee2ad76a6206b8' => ['name' => 'Avatar: Zapovjednica Kitty', 'description' => 'Odaberite ovaj avatar na svom profilu kako biste ga primijenili i profilu dali osobni dodir. Ovaj predmet biti će otključan za sve univerzume na Vašem računu. Imajte na umu da sinkronizacija između univerzuma može potrajati neko vrijeme.', 'duration_label' => 'Trajan', 'extended_description' => 'Brzi refleksi mogu biti blagodat za svakog svemirskog vladara, dok slatka pojava često prikriva lukavi um između tih šiljastih ušiju.'],
    'c70f11e9543100622e3ef3bdcd57099a63f148bf' => ['name' => 'Avatar: Sudbina', 'description' => 'Odaberite ovaj avatar na svom profilu kako biste ga primijenili i profilu dali osobni dodir. Ovaj predmet biti će otključan za sve univerzume na Vašem računu. Imajte na umu da sinkronizacija između univerzuma može potrajati neko vrijeme.', 'duration_label' => 'Trajan', 'extended_description' => 'Bezbroj je sukoba koji su u golemim prostranstvima svemira riješeni pokretom D20. Lica ove kocke su prazna - koje će odluke donijeti?'],
    'ac5bd99552a23733f7b0decac45094d5bfbfedac' => ['name' => 'Avatar: Gorući Bijes', 'description' => 'Odaberite ovaj avatar na svom profilu kako biste ga primijenili i profilu dali osobni dodir. Ovaj predmet biti će otključan za sve univerzume na Vašem računu. Imajte na umu da sinkronizacija između univerzuma može potrajati neko vrijeme.', 'duration_label' => 'Trajan', 'extended_description' => 'Neki vladari među zvijezdama utjeruju strah u ljudska srca gdje god se ugledaju njihove flote. Samo bi budala izazvala njihov bijes.'],
    'da8b1dcf6a9defb45e456968d3c8587bf63a48b5' => ['name' => 'Ograničeni avatar: Horizont Događaja', 'description' => 'Odaberite ovaj avatar na svom profilu kako biste ga primijenili i profilu dali osobni dodir. Ovaj predmet biti će otključan za sve univerzume na Vašem računu. Imajte na umu da sinkronizacija između univerzuma može potrajati neko vrijeme.', 'duration_label' => 'Trajan', 'extended_description' => 'Kako se ispostavilo, izreka starog istraživača o hrabrom odlasku preko horizonta ima svoja ograničenja kada su u pitanju svemirska putovanja...'],
    '69719df021ec40424225f22e2edca15b799401a5' => ['name' => 'Ograničeni avatar: Zvjezdani Pilot', 'description' => 'Odaberite ovaj avatar na svom profilu kako biste ga primijenili i profilu dali osobni dodir. Ovaj predmet biti će otključan za sve univerzume na Vašem računu. Imajte na umu da sinkronizacija između univerzuma može potrajati neko vrijeme.', 'duration_label' => 'Trajan', 'extended_description' => 'Najtalentiraniji brodski kolege, najoštriji piloti i najveći umovi nose nasljeđe čovječanstva daleko izvan zvijezda.'],
    'facb9419f24c4a1fbff7dc29376c3f57c6204c1c' => ['name' => 'Ograničeni Avatar: Android', 'description' => 'Odaberite ovaj avatar na svom profilu kako biste ga primijenili i profilu dali osobni dodir. Ovaj predmet biti će otključan za sve univerzume na Vašem računu. Imajte na umu da sinkronizacija između univerzuma može potrajati neko vrijeme.', 'duration_label' => 'Trajan', 'extended_description' => 'Potpuno mehaničke posade mogu biti posebno korisne u neprijateljskim okruženjima. Također im je potrebno manje prostora za prtljagu, dok tehnologija brzog punjenja znači da oporavak na stanici za punjenje traje kraće nego konvencionalno spavanje. Od uvođenja naprednih baterijskih sustava, nijedan od njih ne mora trpjeti poniženje vezanja za kabel za punjenje, čak ni na ledenim planetima.'],
    '74bf9741209dc8ef4f9996b8b2b7ca59001ea3a8' => ['name' => 'Ograničeni avatar: Zvjezdana Kornjača', 'description' => 'Odaberite ovaj avatar na svom profilu kako biste ga primijenili i profilu dali osobni dodir. Ovaj predmet biti će otključan za sve univerzume na Vašem računu. Imajte na umu da sinkronizacija između univerzuma može potrajati neko vrijeme.', 'duration_label' => 'Trajan', 'extended_description' => 'Iako postojanje zvjezdanih kornjača ostaje kontroverzna tema među stručnjacima, glasine tvrdoglavo traju. Izvješća o viđenjima redovito povezuju vrstu s debelokožcima, ravnim nebeskim tijelima i svim vrstama drugih neobičnosti...'],
    '07a4b64949fcc593435cfaa9184290af96ffdc29' => ['name' => 'Ograničeni avatar: Nakovanj Sudbine', 'description' => 'Odaberite ovaj avatar na svom profilu kako biste ga primijenili i profilu dali osobni dodir. Ovaj predmet biti će otključan za sve univerzume na Vašem računu. Imajte na umu da sinkronizacija između univerzuma može potrajati neko vrijeme.', 'duration_label' => 'Trajan', 'extended_description' => 'Svaki car drži sudbinu svog galaktičkog carstva u svojim rukama. Sami kujete ovu sudbinu, jer vaš talent i predviđanje odlučuju između pobjede i poraza.'],
